// pubspec.yaml:
//   firebase_core: ^2.24.0
//   firebase_crashlytics: ^3.4.9

import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_crashlytics/firebase_crashlytics.dart';
import 'package:flutter/foundation.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp();

  // Only report in release; keep debug crashes local so devs see them fast.
  await FirebaseCrashlytics.instance
      .setCrashlyticsCollectionEnabled(!kDebugMode);

  // 1. Framework errors (build/layout/paint)
  FlutterError.onError = FirebaseCrashlytics.instance.recordFlutterFatalError;

  // 2. Async errors that bubble past every zone
  PlatformDispatcher.instance.onError = (error, stack) {
    FirebaseCrashlytics.instance.recordError(error, stack, fatal: true);
    return true;  // handled
  };

  // 3. Wrap runApp in a Zone for print + uncaught errors from callbacks
  runZonedGuarded(() => runApp(const MyApp()), (e, s) {
    FirebaseCrashlytics.instance.recordError(e, s, fatal: true);
  });
}

// ────── Context you should ALWAYS set ──────
final cr = FirebaseCrashlytics.instance;
await cr.setUserIdentifier(user.uid);           // deletes on sign-out
await cr.setCustomKey('screen', 'checkout');
await cr.setCustomKey('tenant', tenantId);
await cr.setCustomKey('remote_config_variant', variant);
await cr.setCustomKey('offline', isOffline);

// ────── Breadcrumbs — appear on the next report ──────
cr.log('user_tapped: add_to_cart');
cr.log('cart_size: ${cart.length}');

// ────── Non-fatal (handled) ──────
try {
  await api.loadFeed();
} catch (e, s) {
  cr.recordError(e, s, reason: 'load feed', fatal: false);
  // fatal: false = shows as non-fatal, does NOT lower crash-free-users %
}

// ────── Force test crash ──────
if (kDebugMode) cr.crash();  // hard native crash to prove wiring works

// ────── Sign-out hygiene ──────
await cr.setUserIdentifier('');
